import {mkdtempSync,mkdirSync} from 'node:fs';import {join,dirname} from 'node:path';import {tmpdir} from 'node:os';
import {AgentStartLedger,DedicatedAgentAccountLedger,digest} from '../../packages/runtime-adapter/dist/index.js';
import {writeInstance,openLocalProject} from '../../packages/local-app/dist/index.js';
import {createAgentRunProject} from './agent-run-project.js';
import {readHumanOriginalAgentRunInputs} from '../../packages/local-app/src/agent-runtime-control-local.js';
// Actual Kernel/SQLite originals, public constructed bill authentication only.
// No Native/model/key/network/real-bill qualification. Owned originals retained.
export function createAccountBillingEntry(){
 const base=mkdtempSync(join(tmpdir(),'cimiloop-billing-entry-')),root=join(base,'repo'),accountRoot=join(base,'account');mkdirSync(root);const f=createAgentRunProject(root),runId=f.reserveAgent(f.prepareAgent()).run.id;
 writeInstance(join(dirname(f.path),'instance.json'),{schema_version:'1.0.0',instance_id:f.project.instance_id,project_id:f.project.id,actor_id:f.actor.id,created_at:f.project.created_at});
 const local=openLocalProject({projectDir:root}),scope=readHumanOriginalAgentRunInputs(local,runId).scope;
 const origin=AgentStartLedger.initialize(join(base,'host'),{machine_digest:digest('public host').value,principal_digest:digest('public principal').value});
 const connection={format:'cimiloop/dedicated-model/1.0.0' as const,provider:'zhipuai-coding-plan' as const,model:'zhipuai-coding-plan/glm-fixture',credential_file:join(root,'ABSENT-PUBLIC-CREDENTIAL'),credential_digest:digest('public credential identity')};
 const policy={format:'cimiloop/dedicated-agent-account/1.0.0' as const,host_identity_digest:origin.identityDigest,account_digest:digest(root+' public account').value,approval_digest:digest('public approval').value,package_digest:digest('public package').value,tariff_digest:digest('public tariff').value,admission_digest:digest('public admission').value,connection_digest:digest(JSON.stringify(connection)).value,profile:{model:'glm-fixture',thinking:'enabled' as const},cash_limit_micros:60,credit_limit_micro_units:20,cash_per_call_upper_micros:30,credit_per_call_upper_micro_units:10,input_token_limit:1000000,output_token_limit:512};
 const projections=new Map<string,unknown>(),options={origin,repositoryPath:root,root:accountRoot,connection,admission:{check:async()=>{}},custody:{protect:()=>{},verify:()=>{}},billing:{identity_digest:digest('public verifier').value,currency:'CNY',credit_unit:'coding_request_micro_units',verifyOriginal:(bytes:Uint8Array)=>{if(!projections.has(digest(bytes).value))throw Error('unproven public original');return projections.get(digest(bytes).value);}}},account=DedicatedAgentAccountLedger.initialize({...options,policy});
 const addBill=async()=>{const body=Buffer.from('PUBLIC CONSTRUCTED original request'),request={scope_digest:digest(JSON.stringify(scope)).value,admission_digest:policy.admission_digest,connection_digest:policy.connection_digest,call_id:'model_0001',request_id:digest(root+'public request').value,request_digest:digest(body).value,input_bytes:body.length,max_output_tokens:512},hold=await account.reserve(scope,request,body),bytes=Buffer.from('PUBLIC CONSTRUCTED original final bill');
  projections.set(digest(bytes).value,{format:'cimiloop/dedicated-account-bill/1.0.0',bill_id:'public-final-1',account_digest:policy.account_digest,approval_digest:policy.approval_digest,package_digest:policy.package_digest,tariff_digest:policy.tariff_digest,connection_digest:policy.connection_digest,currency:'CNY',credit_unit:'coding_request_micro_units',items:[{request_id:request.request_id,scope_digest:request.scope_digest,call_id:request.call_id,request_digest:request.request_digest,hold_digest:digest(JSON.stringify(hold)).value,cash_charged_micros:12,credit_charged_micro_units:4}]});account.observeBill(bytes);
 };
 return{base,root,accountRoot,f,runId,local,scope,origin,account,policy,connection,projections,addBill,openAccount:()=>DedicatedAgentAccountLedger.open({...options,accountDigest:policy.account_digest}),close(){account.close();origin.close();local.store.close();f.store.close();}};
}
